macro_rules! deps {
    () => {
        AssistContext!();
        Assists!();
        AssistConfig!();
        ExpectedResult!();
    };
}

macro_rules! check_with_config {
    () => {
        deps!();
        # [track_caller] fn check_with_config (config : AssistConfig , handler : Handler , before : & str , expected : ExpectedResult < '_ > , assist_label : Option < & str > ,) { let _tracing = setup_tracing () ; let (mut db , file_with_caret_id , range_or_offset) = RootDatabase :: with_range_or_offset (before) ; db . enable_proc_attr_macros () ; let text_without_caret = db . file_text (file_with_caret_id . file_id (& db)) . text (& db) . to_string () ; let frange = hir :: FileRange { file_id : file_with_caret_id , range : range_or_offset . into () } ; let sema = Semantics :: new (& db) ; let ctx = AssistContext :: new (sema , & config , frange) ; let resolve = match expected { ExpectedResult :: Unresolved => AssistResolveStrategy :: None , _ => AssistResolveStrategy :: All , } ; let mut acc = Assists :: new (& ctx , resolve) ; hir :: attach_db (& db , | | { HirDatabase :: zalsa_register_downcaster (& db) ; handler (& mut acc , & ctx) ; }) ; let mut res = acc . finish () ; let assist = match assist_label { Some (label) => res . into_iter () . find (| resolved | resolved . label == label) , None if res . is_empty () => None , None => Some (res . swap_remove (0)) , } ; match (assist , expected) { (Some (assist) , ExpectedResult :: After (after)) => { let source_change = assist . source_change . filter (| it | ! it . source_file_edits . is_empty () || ! it . file_system_edits . is_empty ()) . expect ("Assist did not contain any source changes") ; let skip_header = source_change . source_file_edits . len () == 1 && source_change . file_system_edits . is_empty () ; let mut buf = String :: new () ; for (file_id , (edit , snippet_edit)) in source_change . source_file_edits { let mut text = db . file_text (file_id) . text (& db) . as_ref () . to_owned () ; edit . apply (& mut text) ; if let Some (snippet_edit) = snippet_edit { snippet_edit . apply (& mut text) ; } if ! skip_header { let source_root_id = db . file_source_root (file_id) . source_root_id (& db) ; let sr = db . source_root (source_root_id) . source_root (& db) ; let path = sr . path_for_file (& file_id) . unwrap () ; format_to ! (buf , "//- {}\n" , path) } buf . push_str (& text) ; } for file_system_edit in source_change . file_system_edits { let (dst , contents) = match file_system_edit { FileSystemEdit :: CreateFile { dst , initial_contents } => (dst , initial_contents) , FileSystemEdit :: MoveFile { src , dst } => { (dst , db . file_text (src) . text (& db) . as_ref () . to_owned ()) } FileSystemEdit :: MoveDir { src , src_id , dst } => { (dst , format ! ("{src_id:?}\n{src:?}")) } } ; let source_root_id = db . file_source_root (dst . anchor) . source_root_id (& db) ; let sr = db . source_root (source_root_id) . source_root (& db) ; let mut base = sr . path_for_file (& dst . anchor) . unwrap () . clone () ; base . pop () ; let created_file_path = base . join (& dst . path) . unwrap () ; format_to ! (buf , "//- {}\n" , created_file_path) ; buf . push_str (& contents) ; } assert_eq_text ! (after , & buf) ; } (Some (assist) , ExpectedResult :: Target (target)) => { let range = assist . target ; assert_eq_text ! (& text_without_caret [range] , target) ; } (Some (assist) , ExpectedResult :: Unresolved) => assert ! (assist . source_change . is_none () , "unresolved assist should not contain source changes") , (Some (_) , ExpectedResult :: NotApplicable) => panic ! ("assist should not be applicable!") , (None , ExpectedResult :: After (_) | ExpectedResult :: Target (_) | ExpectedResult :: Unresolved ,) => { panic ! ("code action is not applicable") } (None , ExpectedResult :: NotApplicable) => () , } ; }
    };
}

check_with_config!()